def need(x,message):
 if not x:raise ValueError(message)
def unpack(destination):
 need(not sys.flags.optimize,'Python optimization unsupported')
 destination=Path(destination)
 need(not destination.is_symlink(),'Symlink source root')
 destination=destination.resolve();destination.mkdir(parents=True,exist_ok=True)
 owner=destination/'.source-owner.json'
 if owner.exists():
  need(not owner.is_symlink() and json.loads(owner.read_text())=={'payload_sha256':PAYLOAD_SHA256},'Unowned extracted source')
  actual={str(p.relative_to(destination)) for p in destination.rglob('*') if p.is_file()}
  need(actual<=set(SOURCE_MANIFEST)|{'.source-owner.json'},'Unexpected files in source root')
 else:
  need(not any(destination.iterdir()),'Nonempty unowned source root')
  owner.write_text(json.dumps({'payload_sha256':PAYLOAD_SHA256})+'\n')
 blob=base64.b85decode(PAYLOAD)
 need(hashlib.sha256(blob).hexdigest()==PAYLOAD_SHA256,'Payload hash')
 with tarfile.open(fileobj=io.BytesIO(gzip.decompress(blob)),mode='r:') as tar:
  members=tar.getmembers()
  need(len(members)==len(SOURCE_MANIFEST) and {x.name for x in members}==set(SOURCE_MANIFEST),'Source member inventory')
  for member in members:
   path=Path(member.name)
   need(member.isfile() and not path.is_absolute() and '..' not in path.parts,'Unsafe source member')
   target=destination/path
   need(target.resolve().is_relative_to(destination) and not target.is_symlink(),'Source path escapes root')
   need(all(not parent.is_symlink() for parent in target.parents if parent!=destination.parent),'Symlink source ancestor')
   data=tar.extractfile(member).read()
   need(hashlib.sha256(data).hexdigest()==SOURCE_MANIFEST[member.name],'Source digest')
   target.parent.mkdir(parents=True,exist_ok=True)
   need(not target.exists() or target.is_file() and hashlib.sha256(target.read_bytes()).hexdigest()==SOURCE_MANIFEST[member.name],'Modified extracted source')
   target.write_bytes(data)
 return destination

def main():
 parser=argparse.ArgumentParser(add_help=False)
 parser.add_argument('--private',type=Path,default=Path('transient-memory-output'))
 parser.add_argument('--cache',type=Path,default=Path('transient-memory-build'))
 parser.add_argument('--extract-only',action='store_true')
 args,remaining=parser.parse_known_args()
 need(not args.private.is_symlink(),'Symlink report root')
 private=args.private.resolve()
 root=unpack(private.parent/('transient-memory-source-'+PAYLOAD_SHA256[:16]))
 if args.extract_only:
  print(json.dumps({'source_only':True,'payload_sha256':PAYLOAD_SHA256,'files':len(SOURCE_MANIFEST)}));return
 subprocess.run([sys.executable,str(root/'runner.py'),'--private',str(private),'--cache',str(args.cache.resolve()),*remaining],check=True,env=dict(os.environ,PYTHONDONTWRITEBYTECODE='1'))
if __name__=='__main__':main()
